rustc_index :: newtype_index ! { # [doc = " During the `InstrumentCoverage` MIR pass, a BCB is a node in the"] # [doc = " \"coverage\u{a0}graph\", which is a refinement of the MIR control-flow graph"] # [doc = " that merges or omits some blocks that aren't relevant to coverage."] # [doc = ""] # [doc = " After that pass is complete, the coverage graph no longer exists, so a"] # [doc = " BCB is effectively an opaque ID."] # [derive (HashStable)] # [encodable] # [orderable] # [debug_format = "bcb{}"] pub struct BasicCoverageBlock { const START_BCB = 0 ; } }